                target: "ESNext",
                module: "ESNext",
                moduleDetection: "force",
                jsx: "react-jsx",
                allowJs: true,
                types: ["@tscircuit/react-fiber"],
                baseUrl: ".",
                moduleResolution: "bundler",
                allowImportingTsExtensions: true,
                verbatimModuleSyntax: true,
                noEmit: true,
                strict: true,
                skipLibCheck: true,
                noFallthroughCasesInSwitch: true,
                noUnusedLocals: false,
